library IEEE;
use IEEE.STD_LOGIC_1164.ALL;
use IEEE.NUMERIC_STD.ALL;

entity register_file is
    port(
        clk             : in std_logic;
        rst             : in std_logic;
        reg_write_enable  : in std_logic;
        write_reg_index   : in std_logic_vector(4 downto 0);
        read_reg1_index   : in std_logic_vector(4 downto 0);
        read_reg2_index   : in std_logic_vector(4 downto 0);
        data_in         : in std_logic_vector(31 downto 0);
        reg_data_out1     : out std_logic_vector(31 downto 0);
        reg_data_out2     : out std_logic_vector(31 downto 0)
    );
end register_file;

architecture Behavioral of register_file is
    type registers_t is array (0 to 31) of std_logic_vector(31 downto 0);
    signal registers : registers_t := (others => (others => '0'));
begin

    -- Write operation
    process(clk, rst)
    begin
        if rst = '1' then
            for i in 0 to 31 loop
                registers(i) <= (others => '0');
            end loop;
        elsif rising_edge(clk) then
            if reg_write_enable = '1' and write_reg_index /= "00000" then
                registers(to_integer(unsigned(write_reg_index))) <= data_in;
            end if;
        end if;
    end process;

    -- Read operations
    reg_data_out1 <= registers(to_integer(unsigned(read_reg1_index)));
    reg_data_out2 <= registers(to_integer(unsigned(read_reg2_index)));

end Behavioral;
