                pc_next_src   <= PC_NEXT_SRC_PC_4;
                branch_type   <= BRANCH_TYPE_NONE;
                rd_data_source <= RD_DATA_SOURCE_ALU_RESULT;

        end case;
    end process;

end Behavioral;
