                    pc <= std_logic_vector(unsigned(pc) + unsigned(immediate_value));
                when PC_NEXT_SRC_PC_4 =>
                    pc <= std_logic_vector(unsigned(pc) + 4);
            end case;

            -- Handle branches
            if branch_type /= BRANCH_TYPE_NONE then
                case branch_type is
                    when BRANCH_TYPE_BEQ =>
                        if reg_data_out1 = reg_data_out2 then
                            pc <= alu_result;
                        end if;
                    when BRANCH_TYPE_BNE =>
                        if reg_data_out1 /= reg_data_out2 then
                            pc <= alu_result;
                        end if;
                    when BRANCH_TYPE_BLT =>
                        if signed(reg_data_out1) < signed(reg_data_out2) then
