        alu_op_type   <= ALU_OP_TYPE_ADD; -- Default value
        reg_write_enable <= '0';          -- Default value
        write_reg_index <= (others => '0');-- Default value
        read_reg1_index <= instr(19 downto 15);
        read_reg2_index <= instr(24 downto 20);
        mem_access_width <= MEM_ACCESS_WIDTH_32; -- Default value
        mem_write_enable <= '0';          -- Default value
