                    when INSTR_FUNCT3_LH => mem_access_width <= MEM_ACCESS_WIDTH_16;
                    when INSTR_FUNCT3_LW => null;
                    when INSTR_FUNCT3_LBU => mem_access_width <= MEM_ACCESS_WIDTH_8;
                    when INSTR_FUNCT3_LHU => mem_access_width <= MEM_ACCESS_WIDTH_16;
                    when others => null;
                end case;

