                alu_op_type <= ALU_OP_TYPE_ADD;
                mem_write_enable <= '1';
                mem_access_width <= MEM_ACCESS_WIDTH_32; -- Default value
                case funct3 is
                    when INSTR_FUNCT3_SB => mem_access_width <= MEM_ACCESS_WIDTH_8;
